const body = $('Webhook IA').item.json.body || {};
const userPrompt = body.prompt || 'Resume el estado general del inventario';
const context = body.context || {};

const products = context.products || [];
const movements = context.movements || [];
const alerts = context.alerts || [];
const categories = context.categories || [];

const totalProducts = products.length;
const outOfStock = products.filter(p => Number(p.stock) <= 0);
const lowStock = products.filter(p => Number(p.stock) > 0 && Number(p.stock) <= Number(p.minimumStock));
const totalValue = products.reduce((acc, p) => acc + (Number(p.stock) * Number(p.purchasePrice || 0)), 0);
const criticalAlerts = alerts.filter(a => a.status === 'critical' || a.status === 'active');

const familyCodes = {
  '1': 'TEC',
  '2': 'FER',
  '3': 'ALI',
  '4': 'FAR',
  '5': 'OFI',
  '6': 'TEX',
  '7': 'AUT'
};

const standardCategories = [
  { id: '1', name: 'Tecnología y Electrónica', code: 'TEC', keywords: ['tecnologia', 'electronica', 'tec', 'computo'] },
  { id: '2', name: 'Ferretería y Construcción', code: 'FER', keywords: ['ferreteria', 'construccion', 'fer', 'herramientas'] },
  { id: '3', name: 'Alimentos y Bebidas', code: 'ALI', keywords: ['alimentos', 'bebidas', 'ali', 'comida'] },
  { id: '4', name: 'Farmacia y Salud', code: 'FAR', keywords: ['farmacia', 'salud', 'far', 'frmacia', 'medico', 'medicamentos', 'botiquin', 'antibacterial'] },
  { id: '5', name: 'Oficina y Papelería', code: 'OFI', keywords: ['oficina', 'papeleria', 'ofi', 'toner', 'papel'] },
  { id: '6', name: 'Textil y Uniformes', code: 'TEX', keywords: ['textil', 'uniformes', 'tex', 'ropa'] },
  { id: '7', name: 'Repuestos Automotrices', code: 'AUT', keywords: ['repuestos', 'automotriz', 'aut', 'mecanica'] }
];

const catList = categories.length > 0 ? categories : standardCategories;

// Detección de consulta específica de categoría
let categoryDirectInfo = '';
const promptLower = (userPrompt || '').toLowerCase();
for (const cat of standardCategories) {
  const catCode = cat.code;
  const catNameLower = cat.name.toLowerCase();
  const keywords = [catNameLower, catCode.toLowerCase(), ...(cat.keywords || [])];

  if (keywords.some(k => k && promptLower.includes(k))) {
    const catProducts = products.filter(p => {
      if (String(p.categoryId) === String(cat.id)) return true;
      if (p.sku && catCode && p.sku.toUpperCase().startsWith(catCode)) return true;
      if (p.category && p.category.toLowerCase().includes(catNameLower)) return true;
      return false;
    });

    categoryDirectInfo = `
=======================================================
🚨 RESPUESTA EXACTA REQUERIDA PARA ESTA CONSULTA:
- Categoría consultada: ${cat.name} (Familia Taxonómica: ${catCode})
- CANTIDAD EXACTA DE PRODUCTOS REGISTRADOS: ${catProducts.length} producto(s)
- Listado oficial verificado en base de datos:
${catProducts.map((p, i) => `  ${i+1}. ${p.name} | SKU: ${p.sku} | Marca: ${p.brand || 'Genérica'} | Stock: ${p.stock} (Mínimo: ${p.minimumStock}) | Estado: ${Number(p.stock) <= 0 ? '🔴 Agotado' : Number(p.stock) <= Number(p.minimumStock) ? '🟡 Stock Bajo' : '🟢 Disponible (Óptimo)'}`).join('\n') || '  (0 productos registrados)'}
=======================================================
INSTRUCCIÓN CRÍTICA DE RESPUESTA:
1. Responde DIRECTAMENTE informando que en StockPilot hay EXACTAMENTE ${catProducts.length} producto(s) asociado(s) a la categoría ${cat.name} (Familia ${catCode}).
2. Presenta una tabla detallando cada uno de los ${catProducts.length} productos con su SKU, Nombre, Marca, Stock Actual, Stock Mínimo y Estado.
3. Explica la situación del stock de estos productos de acuerdo a sus niveles actuales y mínimos de seguridad.
4. NUNCA digas que hay 0 productos o que no tienes visibilidad de la familia ${catCode}.`;
    break;
  }
}

// Desglose exhaustivo de productos clasificados por categoría
const categoryBreakdown = catList.map(cat => {
  const catCode = cat.code || familyCodes[String(cat.id)] || 'GEN';
  const catProducts = products.filter(p => {
    if (String(p.categoryId) === String(cat.id)) return true;
    if (p.sku && p.sku.toUpperCase().startsWith(catCode)) return true;
    if (p.category && p.category.toLowerCase().includes(cat.name.toLowerCase())) return true;
    return false;
  });

  const listItems = catProducts.map((p, idx) => 
    `  ${idx + 1}. ${p.name} | SKU: ${p.sku} | Marca: ${p.brand || 'Genérica'} | Stock: ${p.stock} (Mín: ${p.minimumStock}) | Estado: ${Number(p.stock) <= 0 ? 'Agotado' : Number(p.stock) <= Number(p.minimumStock) ? 'Stock Bajo' : 'Disponible'}`
  ).join('\n');

  return `🏷️ CATEGORÍA: ${cat.name} (Familia: ${catCode} | ID: ${cat.id})
- Cantidad de productos asociados: ${catProducts.length} producto(s)
${listItems || '  (Sin productos registrados)'}`;
}).join('\n\n');

// Resumen de salidas recientes
const recentExits = movements.filter(m => m.type === 'EXIT').slice(-10);

const systemContext = `
Eres StockPilot IA, el copiloto logístico e inteligente del sistema de gestión de inventarios StockPilot.

ESTADO ACTUAL DEL INVENTARIO EN TIEMPO REAL:
- Total de referencias SKU registradas: ${totalProducts}
- Valorización total del inventario: $${totalValue.toLocaleString('en-US', { minimumFractionDigits: 2 })} USD
- Artículos agotados (${outOfStock.length}): ${outOfStock.map(p => `${p.name} (SKU: ${p.sku})`).join(', ') || 'Ninguno'}
- Artículos en stock bajo/mínimo (${lowStock.length}): ${lowStock.map(p => `${p.name} (Stock: ${p.stock}, Mín: ${p.minimumStock})`).join(', ') || 'Ninguno'}
- Alertas críticas activas: ${criticalAlerts.length}
- Movimientos recientes registrados: ${movements.length} transacciones (${recentExits.length} salidas analizadas)

=======================================================
DISTRIBUCIÓN Y CATÁLOGO COMPLETO POR CATEGORÍA:
=======================================================
${categoryBreakdown}`;

return {
  systemContext,
  userPrompt,
  chatInput: `${categoryDirectInfo}\n\nContexto general del inventario:\n${systemContext}\n\nConsulta del usuario:\n"${userPrompt}"`,
  metrics: {
    totalProducts,
    outOfStockCount: outOfStock.length,
    lowStockCount: lowStock.length,
    totalValue,
    criticalAlertsCount: criticalAlerts.length
  }
};

const agentOutput = $json.output || $json.text || $json.response || 'Análisis logístico completado con éxito.';

return {
  success: true,
  source: 'n8n_gemini_agent',
  response: agentOutput,
  timestamp: new Date().toISOString()
};
